    private val defaultStudentUser = UserEntity(
        id = "student_bcs_default",
        name = "BCS Student",
        email = "student@bcs.com",
        role = UserRole.STUDENT,
        avatarColorHex = "#8B5CF6",
        streakDays = 0,
        lastActiveDate = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
    )

    private val _currentUser = MutableStateFlow<UserEntity?>(null)
    val currentUser: StateFlow<UserEntity?> = _currentUser.asStateFlow()

    private var currentUserListener: com.google.firebase.firestore.ListenerRegistration? = null

    // --- Authentication & User State ---
    val allUsers: StateFlow<List<UserEntity>> = repository.allUsers
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    val allStudents: StateFlow<List<UserEntity>> = repository.allStudents
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    private var authStateListener: FirebaseAuth.AuthStateListener? = null

    init {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val firebaseUser = authService.currentFirebaseUser
                if (firebaseUser != null) {
                    val fallbackUser = UserEntity(
                        id = firebaseUser.uid,
                        name = firebaseUser.displayName?.ifBlank { null }
                            ?: firebaseUser.email?.substringBefore("@")?.replaceFirstChar { it.uppercase() }
                            ?: "Student",
                        email = firebaseUser.email.orEmpty(),
                        role = UserRole.STUDENT,
                        avatarColorHex = "#8B5CF6",
                        streakDays = 0,
                        lastActiveDate = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
                    )
                    val restoredUser = restoreOrCreateUserProfile(fallbackUser, isNewUser = false)
                    _currentUser.value = restoredUser
                    startListeningToCurrentUser(restoredUser.id)
                } else {
                    _currentUser.value = null
                }
            } catch (e: Exception) {
                // Ignore any auth check failure on cold start
                _currentUser.value = null
            } finally {
                _isProfileLoading.value = false
            }

            try {
                repository.startFirestoreSync(viewModelScope)
            } catch (e: Exception) {
                // Ignore sync errors on cold start
            }
        }
        
        // Auto-reconnect Firestore listeners when Firebase Auth state becomes valid
        authStateListener = FirebaseAuth.AuthStateListener { auth ->
            val user = auth.currentUser
            if (user != null) {
                viewModelScope.launch {
                    try {
                        repository.startFirestoreSync(viewModelScope)
                    } catch (e: Exception) {
                        // Ignore
                    }
                }
            } else {
                _currentUser.value = null
                currentUserListener?.remove()
                currentUserListener = null
            }
        }
        try {
            FirebaseAuth.getInstance().addAuthStateListener(authStateListener!!)
        } catch (e: Exception) {
            // Ignore if Firebase isn't initialized
        }
    }

    private suspend fun restoreOrCreateUserProfile(
        authenticatedUser: UserEntity,
        isNewUser: Boolean
    ): UserEntity {
        try {
            val existingProfile = firestoreSync.getUser(authenticatedUser.id)
            if (existingProfile != null) {
                repository.insertUser(existingProfile)
                prefs.edit().putString("logged_in_user_id", existingProfile.id).apply()
                return existingProfile
            }
        } catch (e: Exception) {
            // ignore
        }
        
        repository.insertUser(authenticatedUser)
        prefs.edit().putString("logged_in_user_id", authenticatedUser.id).apply()
        return authenticatedUser
    }

    private fun startListeningToCurrentUser(userId: String) {
        currentUserListener?.remove()
        currentUserListener = firestoreSync.observeCurrentUser(userId) { user ->
            _currentUser.value = user
            viewModelScope.launch(Dispatchers.IO) {
                try {
                    repository.insertUser(user)
                } catch (e: Exception) {}
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        authStateListener?.let {
            try {
                FirebaseAuth.getInstance().removeAuthStateListener(it)
            } catch (e: Exception) {
                // Ignore
            }
        }
        repository.stopFirestoreSync()
    }

    fun clearAuthError() {
        _authErrorMessage.value = null
    }

    fun setCurrentUser(user: UserEntity) {
        _currentUser.value = user
        prefs.edit().putString("logged_in_user_id", user.id).apply()
    }

    fun logout() {
        authService.signOut()
        _currentUser.value = null
        prefs.edit().remove("logged_in_user_id").apply()
        repository.stopFirestoreSync()
        viewModelScope.launch {
            _eventFlow.emit(UiEvent.ShowToast("Signed out successfully"))
        }
    }

    /**
     * Firebase Google Sign-In with Credential Manager
     */
    fun signInWithGoogle(activityContext: Context) {
        viewModelScope.launch(Dispatchers.IO) {
            _isAuthLoading.value = true
            _authErrorMessage.value = null
            when (val result = authService.signInWithGoogle(activityContext)) {
                is AuthResultState.Success -> {
                    val restoredUser = restoreOrCreateUserProfile(result.user, result.isNewUser)
                    _currentUser.value = restoredUser
                    startListeningToCurrentUser(restoredUser.id)
                    _isAuthLoading.value = false
                    try {
                        repository.startFirestoreSync(viewModelScope)
                    } catch (e: Exception) {
                        // Ignore
                    }
                    val msg = if (result.isNewUser) {
                        "Welcome to BCS Diary, ${restoredUser.name}! ✨"
                    } else {
                        "Welcome back, ${restoredUser.name}! 💕"
                    }
                    _eventFlow.emit(UiEvent.ShowToast(msg))
                }
                is AuthResultState.Error -> {
                    _isAuthLoading.value = false
                    _authErrorMessage.value = result.message
                    _eventFlow.emit(UiEvent.ShowToast(result.message))
                }
                is AuthResultState.Cancelled -> {
                    _isAuthLoading.value = false
                }
            }
        }
    }

    /**
     * Quick Demo Sign-In for testing without Google Credentials
     */
    fun signInWithDemoStudent() {
        viewModelScope.launch(Dispatchers.IO) {
            _isAuthLoading.value = true
            _authErrorMessage.value = null
            val today = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date())
            val demoUser = UserEntity(
