            if (isCompleted) {
                _celebrationState.value = CelebrationData(title = "Task Completed!", message = "You're doing great!")
                val completion = TaskCompletionEntity(
                    id = UUID.randomUUID().toString(),
                    taskId = task.task.id,
                    userId = _currentUser.value?.id ?: "",
                    completionDate = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date()),
                    notes = note ?: ""
                )
                repository.insertCompletion(completion)
            }
        }
    }

