    private val _selectedSubjectFilter = MutableStateFlow<String?>(null)
    val selectedSubjectFilter: StateFlow<String?> = _selectedSubjectFilter.asStateFlow()
    fun setSubjectFilter(subjectId: String?) { _selectedSubjectFilter.value = subjectId }

    private val _taskFilter = MutableStateFlow(TaskFilter.ALL)
    val taskFilter: StateFlow<TaskFilter> = _taskFilter.asStateFlow()
    fun setTaskFilter(filter: TaskFilter) { _taskFilter.value = filter }

    private val _activeTab = MutableStateFlow(StudentTab.TASKS)
    val activeTab: StateFlow<StudentTab> = _activeTab.asStateFlow()
    fun setActiveTab(tab: StudentTab) { _activeTab.value = tab }

    private val _isDarkTheme = MutableStateFlow<Boolean?>(null)
    val isDarkTheme: StateFlow<Boolean?> = _isDarkTheme.asStateFlow()
    fun toggleDarkTheme(isDark: Boolean) { _isDarkTheme.value = isDark }

    private val _selectedThemeStyle = MutableStateFlow(ThemeStyle.DEFAULT)
    val selectedThemeStyle: StateFlow<ThemeStyle> = _selectedThemeStyle.asStateFlow()
    fun setThemeStyle(style: ThemeStyle) { _selectedThemeStyle.value = style }

    private val _celebrationState = MutableStateFlow<CelebrationData?>(null)
    val celebrationState: StateFlow<CelebrationData?> = _celebrationState.asStateFlow()
    fun dismissCelebration() { _celebrationState.value = null }

    val filteredTasks: StateFlow<List<TaskWithDetails>> = combine(
        tasksWithDetails, _searchQuery, _selectedSubjectFilter, _taskFilter
    ) { tasks, query, subjectFilter, filter ->
        tasks.filter { task ->
            val matchesQuery = task.task.title.contains(query, ignoreCase = true) || task.task.description.contains(query, ignoreCase = true)
            val matchesSubject = subjectFilter == null || task.task.subjectId == subjectFilter
            val matchesFilter = when (filter) {
                TaskFilter.ALL -> true
                TaskFilter.TODAY -> task.task.dueDate == SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
                TaskFilter.PENDING -> !task.task.isCompleted
                TaskFilter.COMPLETED -> task.task.isCompleted
            }
            matchesQuery && matchesSubject && matchesFilter
        }
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    fun toggleTaskCompletion(task: TaskWithDetails, note: String?) {
        viewModelScope.launch(Dispatchers.IO) {
            val isCompleted = !task.task.isCompleted
            repository.updateTask(task.task.copy(isCompleted = isCompleted))
            if (isCompleted) {
                _celebrationState.value = CelebrationData(title = "Task Completed!", message = "You're doing great!")
                val completion = TaskCompletionEntity(
                    id = UUID.randomUUID().toString(),
                    taskId = task.task.id,
                    userId = _currentUser.value?.id ?: "",
                    completionDate = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date()),
                    notes = note ?: ""
                )
                repository.insertCompletion(completion)
            }
        }
    }

