    val filteredTasks: StateFlow<List<TaskWithDetails>> = combine(
        tasksWithDetails, _searchQuery, _selectedSubjectFilter, _taskFilter
    ) { tasks, query, subjectFilter, filter ->
        tasks.filter { task ->
            val matchesQuery = task.task.title.contains(query, ignoreCase = true) || task.task.description.contains(query, ignoreCase = true)
            val matchesSubject = subjectFilter == null || task.task.subjectId == subjectFilter
            val matchesFilter = when (filter) {
                TaskFilter.ALL -> true
                TaskFilter.TODAY -> task.task.dueDate == SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
                TaskFilter.PENDING -> !task.task.isCompleted
                TaskFilter.COMPLETED -> task.task.isCompleted
            }
            matchesQuery && matchesSubject && matchesFilter
        }
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

